using System.Runtime.InteropServices;
namespace LSE.AutoCADElectrical.ProjectTools;
public static class DiagnosticsService{
 public static string BuildReport(){var s=SettingsService.Load();string vault=SettingsService.DiscoverVaultRoot();var x=new List<string>{"LSE Project Tools V2 (Lake Shore Electric)",RuntimeInformation.FrameworkDescription,VaultProbe.Report(""),"Assembly: "+typeof(DiagnosticsService).Assembly.Location,"Settings: "+SettingsService.SettingsPath,"Vault working folder: "+(vault.Length==0?"NOT FOUND (expected "+SettingsService.DefaultVaultRoot+"; defaults fall back to AutoCAD Electrical's own folders)":vault),"Jobs root (Custom Sales Order): "+s.ProjectsRootFolder+(Directory.Exists(s.ProjectsRootFolder)?" (exists)":" (MISSING)"+(VaultProbe.InVaultWorkingFolder(s.ProjectsRootFolder)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":"")),"LSE template project: "+(s.BaseProjectPath.Length==0?"(none)":s.BaseProjectPath+(File.Exists(s.BaseProjectPath)?" (exists)":" (MISSING)"+(VaultProbe.InVaultWorkingFolder(s.BaseProjectPath)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":""))),"Drawing template: "+s.DrawingTemplatePath+(File.Exists(s.DrawingTemplatePath)?" (exists)":" (MISSING)"+(VaultProbe.InVaultWorkingFolder(s.DrawingTemplatePath)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":"")),"Templates JSON: "+s.TemplatesConfigPath,"Symbol library: "+s.SymbolLibraryFolder+(Directory.Exists(s.SymbolLibraryFolder)?" (exists)":" (MISSING)"+(VaultProbe.InVaultWorkingFolder(s.SymbolLibraryFolder)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":"")),"WD_M library file: "+(ProjectTransactionService.FindWdmLibrary(s) is {Length:>0} w?w:"not found"),"Activation LISP: "+s.ActivateProjectLisp,"Copy template .wdt/.wdl: "+s.CopyTemplateSidecars+"   Write .aepx: "+s.WriteAepxFile};
  ProjectTemplates? t=null;try{t=TemplateService.Load(s.TemplatesConfigPath);x.Add($"Templates JSON: PASS ({t.DescriptionLines.Count} description lines, {t.ProductLines.Count} product lines: {string.Join(", ",t.ProductLines.Select(p=>p.Name))}; {t.ProjectTypes.Count} drawing sets: {string.Join(", ",t.ProjectTypes.Select(p=>p.Name))})");x.Add("Job number rule: "+t.Job.NumberPattern+(t.Job.NumberExample.Length>0?" (example "+t.Job.NumberExample+")":"")+"; folder "+t.Job.FolderNamePattern+"; project "+t.Job.ProjectNamePattern+"; files "+t.Job.FileNamePattern);x.Add("Title block names: "+(t.TitleBlock.BlockNames.Count==0?"(any block with a "+t.TitleBlock.SheetAttribute+" attribute)":string.Join(", ",t.TitleBlock.BlockNames)));}catch(Exception ex){x.Add("Templates JSON: FAIL "+ex.Message);}
  string folder=SettingsService.TemplateFolder(s.BaseProjectPath,s.DrawingTemplatePath);if(folder.Length>0&&t is not null){foreach(string f in new[]{t.Vault.DrawingTemplate,t.Vault.CoverTemplate}.Where(n=>n.Trim().Length>0))x.Add("Template folder file "+f+": "+(File.Exists(Path.Combine(folder,f))?"PASS":"MISSING"+(VaultProbe.InVaultWorkingFolder(folder)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":"")));
   if(s.BaseProjectPath.Length>0){x.Add("Template .wdt: "+(WdpFileService.ExistingCaseInsensitive(WdpFileService.MappingPath(s.BaseProjectPath)) is not null?"PASS (copied into new projects)":"MISSING (generated from the JSON instead)"));x.Add("Template _wdtitle.wdl: "+(WdpFileService.ExistingCaseInsensitive(WdpFileService.LabelsPath(s.BaseProjectPath)) is not null?"PASS (copied into new projects)":"MISSING (generated from the JSON instead)"));}
   foreach(var p in t.ProjectTypes)foreach(var d in p.Drawings.Where(d=>d.Template.Trim().Length>0)){string tp=TemplateService.ResolveTemplate(d.Template,folder);if(!File.Exists(tp))x.Add("Drawing set "+p.Name+" sheet "+d.Sheet+" template MISSING: "+tp+(VaultProbe.InVaultWorkingFolder(tp)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":""));}}
  if(t is not null&&File.Exists(s.DrawingTemplatePath))try{var i=DrawingFactoryService.Inspect(s.DrawingTemplatePath,t.TitleBlock,t.Wdm);x.Add("Template WD_M block: "+(i.HasWdm?"PASS":"MISSING (will be inserted from the WD_M library file when available)"));x.Add("Template layouts: "+string.Join(", ",i.Layouts));x.Add(i.TitleBlocks.Count==0?"Template title blocks: NONE matched (expected "+string.Join(", ",t.TitleBlock.BlockNames)+")":"Template title blocks: "+string.Join(" | ",i.TitleBlocks));}catch(Exception ex){x.Add("Template read: FAIL "+ex.Message);}
  if(s.BaseProjectPath.Length>0&&File.Exists(s.BaseProjectPath))try{var b=WdpFileService.Parse(s.BaseProjectPath);x.Add($"Template project read: PASS ({b.Descriptions.Count} descriptions, {b.Options.Count} options, {b.Properties.Count} properties, {b.Drawings.Count} drawings, {WdpFileService.EncodingName(b.Encoding)})");if(b.Options.TryGetValue(2,out var menu))x.Add("Template schematic icon menu: "+menu+(File.Exists(menu)?" (exists)":" (MISSING on this machine)"));}catch(Exception ex){x.Add("Template project read: FAIL "+ex.Message);}
  if(VaultProbe.InVaultWorkingFolder(s.ProjectsRootFolder))x.Add("Jobs root is inside the Vault working folder: new job folders must be added to Vault after creation");
  x.Add("Recent projects: "+s.RecentProjects.Count);return string.Join(Environment.NewLine,x);}
}
